  1→/**
  2→ * Shared type definitions for the thos dashboard.
  3→ *
  4→ * Three categories:
  5→ * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
  6→ *    `--sdk-url` WebSocket connection (CLI → WS server).
  7→ * 2. **Browser ↔ Server** — messages exchanged between the React client
  8→ *    and the standalone WS relay server.
  9→ * 3. **UI state** — view-model types consumed by React components.
 10→ *
 11→ * ## Key architecture notes
 12→ *
 13→ * - On browser connect, the server sends `agent_list` + `task_list` only.
 14→ * - Message histories are loaded lazily: the browser sends
 15→ *   `request_history` when selecting an agent, and the server responds
 16→ *   with `message_history` for that single agent.
 17→ * - Live messages for active agents are broadcast via `relay` in real time.
 18→ * - See `server/ws.ts` and `hooks/use-websocket.ts` for implementation.
 19→ */
 20→
 21→// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────
 22→
 23→/**
 24→ * Sent once after the first user prompt is received. Contains session
 25→ * metadata like the model name, working directory, and available tools.
 26→ */
 27→export interface ClaudeSystemInit {
 28→  type: "system";
 29→  subtype: "init";
 30→  session_id: string;
 31→  tools: unknown[];
 32→  mcp_servers: unknown[];
 33→  model: string;
 34→  cwd: string;
 35→}
 36→
 37→/**
 38→ * An assistant turn. `message.content` is an array of content blocks
 39→ * (text, tool_use, tool_result) that may arrive incrementally — each
 40→ * NDJSON line is a complete snapshot of the message so far.
 41→ */
 42→export interface ClaudeAssistant {
 43→  type: "assistant";
 44→  message: {
 45→    id: string;
 46→    role: "assistant";
 47→    content: AssistantContentBlock[];
 48→    model: string;
 49→    stop_reason: string | null;
 50→  };
 51→  session_id: string;
 52→}
 53→
 54→/** A single content block inside an assistant message. */
 55→export type AssistantContentBlock =
 56→  | { type: "text"; text: string }
 57→  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 58→  | { type: "tool_result"; tool_use_id: string; content: string };
 59→
 60→/**
 61→ * Terminal message for a session. Includes cost/duration metrics.
 62→ * `is_error` is true when `subtype` is `"error"`.
 63→ */
 64→export interface ClaudeResult {
 65→  type: "result";
 66→  subtype: "success" | "error";
 67→  result?: string;
 68→  error?: string;
 69→  session_id: string;
 70→  cost_usd: number;
 71→  total_cost_usd?: number;
 72→  duration_ms: number;
 73→  duration_api_ms: number;
 74→  is_error: boolean;
 75→  num_turns: number;
 76→}
 77→
 78→/**
 79→ * Claude is requesting permission to execute a tool. The dashboard must
 80→ * reply with a `control_response` (allow / deny) before the CLI proceeds.
 81→ *
 82→ * Wire format uses a nested `request` object with `request_id` at the
 83→ * top level for correlation (matches Companion protocol docs).
 84→ */
 85→export interface ClaudeControlRequest {
 86→  type: "control_request";
 87→  request_id: string;
 88→  request: {
 89→    subtype: "can_use_tool";
 90→    tool_name: string;
 91→    input: Record<string, unknown>;
 92→    tool_use_id?: string;
 93→    description?: string;
 94→  };
 95→  session_id?: string;
 96→}
 97→
 98→/**
 99→ * Hook lifecycle events emitted during CLI startup. `hook_response` is
100→ * the signal that the CLI is ready to receive the first user prompt.
101→ */
102→export interface ClaudeSystemHook {
103→  type: "system";
104→  subtype: "hook_started" | "hook_response";
105→  session_id?: string;
106→}
107→
108→/** Discriminated union of all known Claude NDJSON message shapes. */
109→export type ClaudeMessage =
110→  | ClaudeSystemInit
111→  | ClaudeAssistant
112→  | ClaudeResult
113→  | ClaudeControlRequest
114→  | ClaudeSystemHook
115→  | { type: string; subtype?: string; [key: string]: unknown };
116→
117→// ── Workspaces ───────────────────────────────────────────────────────────
118→
119→/** A workspace represents a project directory. */
120→export interface Workspace {
121→  id: string;
122→  name: string;
123→  cwd: string;
124→  createdAt: number;
125→}
126→
127→/** A directory entry returned by the server-side folder browser. */
128→export interface DirectoryEntry {
129→  name: string;
130→  path: string;
131→}
132→
133→// ── Browser ↔ Server messages ─────────────────────────────────────────────
134→
135→/** Browser asks the server to spawn a new Claude CLI process. */
136→export interface BrowserSpawn {
137→  type: "spawn";
138→  prompt: string;
139→  workspaceId?: string;
140→}
141→
142→/** Browser sends a follow-up message to an already-running Claude session. */
143→export interface BrowserSendMessage {
144→  type: "send_message";
145→  agentId: string;
146→  content: string;
147→}
148→
149→/** Browser responds to a tool approval request (allow or deny). */
150→export interface BrowserControlResponse {
151→  type: "control_response";
152→  agentId: string;
153→  request_id: string;
154→  allow: boolean;
155→}
156→
157→/** Browser asks the server to kill a running agent's tmux session + CLI. */
158→export interface BrowserKillAgent {
159→  type: "kill_agent";
160→  agentId: string;
161→}
162→
163→/** Browser asks the server to permanently delete an agent. */
164→export interface BrowserDeleteAgent {
165→  type: "delete_agent";
166→  agentId: string;
167→}
168→
169→/** Browser asks the server to rename an agent. */
170→export interface BrowserRenameAgent {
171→  type: "rename_agent";
172→  agentId: string;
173→  label: string;
174→}
175→
176→/** Browser asks the server to clear an agent's message history. */
177→export interface BrowserClearHistory {
178→  type: "clear_history";
179→  agentId: string;
180→}
181→
182→/** Browser requests message history for a specific agent (lazy loading). */
183→export interface BrowserRequestHistory {
184→  type: "request_history";
185→  agentId: string;
186→}
187→
188→/** Browser asks the server to create a new task. */
189→export interface BrowserCreateTask {
190→  type: "create_task";
191→  title: string;
192→  description: string;
193→  priority: TaskPriority;
194→}
195→
196→/** Browser asks to update a task's fields. */
197→export interface BrowserUpdateTask {
198→  type: "update_task";
199→  taskId: string;
200→  updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>;
201→}
202→
203→/** Browser asks to delete a task. */
204→export interface BrowserDeleteTask {
205→  type: "delete_task";
206→  taskId: string;
207→}
208→
209→/** Browser asks to delegate a task to a new Claude agent. */
210→export interface BrowserDelegateTask {
211→  type: "delegate_task";
212→  taskId: string;
213→}
214→
215→/** Browser tells the server which workspace to scope to. */
216→export interface BrowserSetWorkspace {
217→  type: "set_workspace";
218→  workspaceId: string | null;
219→}
220→
221→/** Browser asks the server to create a new workspace. */
222→export interface BrowserCreateWorkspace {
223→  type: "create_workspace";
224→  name: string;
225→  cwd: string;
226→}
227→
228→/** Browser asks to rename a workspace. */
229→export interface BrowserRenameWorkspace {
230→  type: "rename_workspace";
231→  workspaceId: string;
232→  name: string;
233→}
234→
235→/** Browser asks to delete a workspace. */
236→export interface BrowserDeleteWorkspace {
237→  type: "delete_workspace";
238→  workspaceId: string;
239→}
240→
241→/** Browser asks to browse a directory on the server. */
242→export interface BrowserBrowseDirectory {
243→  type: "browse_directory";
244→  path: string;
245→}
246→
247→/** Union of all messages the browser can send to the WS server. */
248→export type BrowserMessage =
249→  | BrowserSpawn
250→  | BrowserSendMessage
251→  | BrowserControlResponse
252→  | BrowserKillAgent
253→  | BrowserDeleteAgent
254→  | BrowserRenameAgent
255→  | BrowserClearHistory
256→  | BrowserRequestHistory
257→  | BrowserCreateTask
258→  | BrowserUpdateTask
259→  | BrowserDeleteTask
260→  | BrowserDelegateTask
261→  | BrowserSetWorkspace
262→  | BrowserCreateWorkspace
263→  | BrowserRenameWorkspace
264→  | BrowserDeleteWorkspace
265→  | BrowserBrowseDirectory;
266→
267→/** Server relays a raw Claude NDJSON message to the browser. */
268→export interface ServerRelay {
269→  type: "relay";
270→  agentId: string;
271→  message: ClaudeMessage;
272→}
273→
274→/** Server notifies the browser of an agent status change. */
275→export interface ServerStatus {
276→  type: "status";
277→  agentId: string;
278→  status: AgentStatus;
279→}
280→
281→/** Server reports an error (e.g. no active session, process crash). */
282→export interface ServerError {
283→  type: "error";
284→  agentId: string;
285→  error: string;
286→}
287→
288→/** Summary of an agent for the sidebar. */
289→export interface AgentInfo {
290→  agentId: string;
291→  status: AgentStatus;
292→  tmuxSession: string | null;
293→  label: string;
294→  createdAt: number;
295→  workspaceId: string | null;
296→}
297→
298→/** Server sends the full list of agents after every state change. */
299→export interface ServerAgentList {
300→  type: "agent_list";
301→  agents: AgentInfo[];
302→}
303→
304→/** Server confirms a new agent was spawned and assigns its ID. */
305→export interface ServerSpawned {
306→  type: "spawned";
307→  agentId: string;
308→}
309→
310→/** Server sends full message history for an agent (in response to `request_history`). */
311→export interface ServerMessageHistory {
312→  type: "message_history";
313→  agentId: string;
314→  messages: ServerMessage[];
315→}
316→
317→/** CLI WebSocket disconnected (process may have crashed or exited). */
318→export interface ServerCliDisconnected {
319→  type: "cli_disconnected";
320→  agentId: string;
321→}
322→
323→/** CLI WebSocket reconnected (e.g. after relaunch with --resume). */
324→export interface ServerCliConnected {
325→  type: "cli_connected";
326→  agentId: string;
327→}
328→
329→/** Server confirms message history was cleared for an agent. */
330→export interface ServerHistoryCleared {
331→  type: "history_cleared";
332→  agentId: string;
333→}
334→
335→/** Server sends the full workspace list to the browser. */
336→export interface ServerWorkspaceList {
337→  type: "workspace_list";
338→  workspaces: Workspace[];
339→}
340→
341→/** Server responds with a directory listing for the folder browser. */
342→export interface ServerDirectoryListing {
343→  type: "directory_listing";
344→  path: string;
345→  entries: DirectoryEntry[];
346→}
347→
348→/** Server sends the full task list to the browser. */
349→export interface ServerTaskList {
350→  type: "task_list";
351→  tasks: Task[];
352→}
353→
354→/** Server confirms a task was updated. */
355→export interface ServerTaskUpdated {
356→  type: "task_updated";
357→  task: Task;
358→}
359→
360→/** Server confirms a task was deleted. */
361→export interface ServerTaskDeleted {
362→  type: "task_deleted";
363→  taskId: string;
364→}
365→
366→/** Union of all messages the WS server can send to the browser. */
367→export type ServerMessage =
368→  | ServerRelay
369→  | ServerStatus
370→  | ServerError
371→  | ServerAgentList
372→  | ServerSpawned
373→  | ServerMessageHistory
374→  | ServerCliDisconnected
375→  | ServerCliConnected
376→  | ServerHistoryCleared
377→  | ServerWorkspaceList
378→  | ServerDirectoryListing
379→  | ServerTaskList
380→  | ServerTaskUpdated
381→  | ServerTaskDeleted;
382→
383→// ── UI state ──────────────────────────────────────────────────────────────
384→
385→/**
386→ * Lifecycle states of the Claude agent process:
387→ * - `idle`      — no process running, ready to spawn
388→ * - `spawning`  — process launched, waiting for CLI to connect via WS
389→ * - `connected` — CLI connected and `system/init` received
390→ * - `thinking`  — waiting for assistant response
391→ * - `done`      — `result` message received, process finished
392→ * - `error`     — process crashed or unexpected failure
393→ */
394→export type AgentStatus = "idle" | "spawning" | "connected" | "thinking" | "done" | "disconnected" | "error";
395→
396→export type ChatMessageRole = "user" | "assistant" | "system";
397→
398→/**
399→ * A single entry in the chat message list. System messages include
400→ * session init info and result summaries. Messages with a `controlRequest`
401→ * are rendered as tool-approval cards instead of plain bubbles.
402→ */
403→/** A single option in an AskUserQuestion question. */
404→export interface UserQuestionOption {
405→  label: string;
406→  description?: string;
407→}
408→
409→/** A single question from AskUserQuestion. */
410→export interface UserQuestion {
411→  question: string;
412→  header?: string;
413→  options: UserQuestionOption[];
414→  multiSelect: boolean;
415→}
416→
417→/** Info about a single tool_use block in an assistant message. */
418→export interface ToolCallInfo {
419→  name: string;
420→  toolUseId?: string;
421→  /** Truncated one-line preview of the tool result, if available. */
422→  resultPreview?: string;
423→}
424→
425→export interface ChatMessage {
426→  id: string;
427→  role: ChatMessageRole;
428→  content: string;
429→  timestamp: number;
430→  /** Present when this message represents a tool approval request. */
431→  controlRequest?: {
432→    id: string;
433→    tool_name: string;
434→    input: Record<string, unknown>;
435→    /** Tool description from the protocol, if available. */
436→    description?: string;
437→    /** Set to true after the user allows or denies. */
438→    resolved?: boolean;
439→    /** Whether the user allowed (true) or denied (false). */
440→    allowed?: boolean;
441→  };
442→  /** Present when this message is an AskUserQuestion control request. */
443→  userQuestion?: {
444→    requestId: string;
445→    questions: UserQuestion[];
446→    resolved?: boolean;
447→  };
448→  /** Tool calls found in this assistant message. */
449→  toolCalls?: ToolCallInfo[];
450→  /** True when this message has only tool_use/tool_result blocks and no text. */
451→  isToolOnly?: boolean;
452→}
453→
454→// ── Task system ──────────────────────────────────────────────────────────
455→
456→export type TaskStatus = "icebox" | "todo" | "in-progress" | "done";
457→export type TaskPriority = "low" | "medium" | "high" | "urgent";
458→
459→/** A user-created task, optionally linked to a Claude agent. */
460→export interface Task {
461→  id: string;
462→  title: string;
463→  description: string;
464→  status: TaskStatus;
465→  priority: TaskPriority;
466→  /** If delegated, the agentId of the spawned Claude agent. */
467→  agentId: string | null;
468→  /** Workspace this task belongs to. */
469→  workspaceId: string | null;
470→  createdAt: number;
471→  updatedAt: number;
472→}
