  1→"use client";
  2→
  3→/**
  4→ * Single chat message bubble.
  5→ * - **user** — right-aligned, primary background.
  6→ * - **assistant** — left-aligned, secondary background, markdown rendered.
  7→ * - **system** — centered, italic, muted (used for init info, result summaries, errors).
  8→ *
  9→ * Includes:
 10→ * - Relative timestamps ("just now", "2m ago") with absolute time on hover.
 11→ * - Copy button on hover for user/assistant messages.
 12→ * - Markdown rendering for assistant messages via react-markdown + remark-gfm.
 13→ */
 14→
 15→import { useEffect, useState } from "react";
 16→import { Check, Copy } from "lucide-react";
 17→import Markdown from "react-markdown";
 18→import remarkGfm from "remark-gfm";
 19→import type { ChatMessage } from "@/lib/types";
 20→import { cn } from "@/lib/utils";
 21→
 22→// ── Relative time formatting ────────────────────────────────────────────
 23→
 24→function formatRelativeTime(ts: number): string {
 25→  const diff = Date.now() - ts;
 26→  if (diff < 10_000) return "just now";
 27→  if (diff < 60_000) return `${Math.floor(diff / 1000)}s ago`;
 28→  if (diff < 3_600_000) return `${Math.floor(diff / 60_000)}m ago`;
 29→  if (diff < 86_400_000) return `${Math.floor(diff / 3_600_000)}h ago`;
 30→  return `${Math.floor(diff / 86_400_000)}d ago`;
 31→}
 32→
 33→function formatAbsoluteTime(ts: number): string {
 34→  return new Date(ts).toLocaleString();
 35→}
 36→
 37→function RelativeTime({ timestamp }: { timestamp: number }) {
 38→  const [, setTick] = useState(0);
 39→
 40→  useEffect(() => {
 41→    const id = setInterval(() => setTick((t) => t + 1), 30_000);
 42→    return () => clearInterval(id);
 43→  }, []);
 44→
 45→  return (
 46→    <time
 47→      dateTime={new Date(timestamp).toISOString()}
 48→      title={formatAbsoluteTime(timestamp)}
 49→      className="text-[10px] text-muted-foreground/60"
 50→    >
 51→      {formatRelativeTime(timestamp)}
 52→    </time>
 53→  );
 54→}
 55→
 56→// ── Copy button ─────────────────────────────────────────────────────────
 57→
 58→function CopyButton({ text }: { text: string }) {
 59→  const [copied, setCopied] = useState(false);
 60→
 61→  function handleCopy() {
 62→    navigator.clipboard.writeText(text).then(() => {
 63→      setCopied(true);
 64→      setTimeout(() => setCopied(false), 1500);
 65→    });
 66→  }
 67→
 68→  return (
 69→    <button
 70→      onClick={handleCopy}
 71→      className="absolute top-1 right-1 rounded p-1 opacity-0 transition-opacity hover:bg-muted/50 group-hover:opacity-100"
 72→      aria-label="Copy message"
 73→    >
 74→      {copied ? (
 75→        <Check className="size-3 text-green-400" />
 76→      ) : (
 77→        <Copy className="size-3 text-muted-foreground" />
 78→      )}
 79→    </button>
 80→  );
 81→}
 82→
 83→// ── Message component ───────────────────────────────────────────────────
 84→
 85→export function Message({ message }: { message: ChatMessage }) {
 86→  if (message.role === "system") {
 87→    return (
 88→      <div className="py-1 text-center text-xs italic text-muted-foreground">
 89→        {message.content}
 90→      </div>
 91→    );
 92→  }
 93→
 94→  const isUser = message.role === "user";
 95→
 96→  return (
 97→    <div className={cn("flex flex-col gap-0.5", isUser ? "items-end" : "items-start")}>
 98→      <div
 99→        className={cn(
100→          "group relative max-w-[90%] md:max-w-[80%] rounded-lg px-3 py-2 text-sm",
101→          isUser
102→            ? "bg-primary text-primary-foreground whitespace-pre-wrap"
103→            : "bg-secondary text-secondary-foreground prose-msg"
104→        )}
105→      >
106→        {isUser ? (
107→          message.content
108→        ) : (
109→          <Markdown remarkPlugins={[remarkGfm]}>{message.content}</Markdown>
110→        )}
111→        <CopyButton text={message.content} />
112→      </div>
113→      <RelativeTime timestamp={message.timestamp} />
114→    </div>
115→  );
116→}
