 1→"use client";
 2→
 3→import { useState } from "react";
 4→import { ChevronRight } from "lucide-react";
 5→import type { CondensedGroup } from "@/lib/condense-messages";
 6→import type { ToolCallInfo } from "@/lib/types";
 7→import { Message } from "./message";
 8→import { cn } from "@/lib/utils";
 9→
10→/** Colored dot per common tool name. */
11→const TOOL_COLORS: Record<string, string> = {
12→  Read: "bg-blue-400",
13→  Write: "bg-green-400",
14→  Edit: "bg-yellow-400",
15→  Bash: "bg-orange-400",
16→  Glob: "bg-purple-400",
17→  Grep: "bg-cyan-400",
18→  WebFetch: "bg-pink-400",
19→  Task: "bg-indigo-400",
20→  TodoWrite: "bg-teal-400",
21→};
22→
23→export function CondensedToolGroup({ group }: { group: CondensedGroup }) {
24→  const [expanded, setExpanded] = useState(false);
25→
26→  // Collect all tool calls with previews for the collapsed view
27→  const allToolCalls: ToolCallInfo[] = [];
28→  for (const msg of group.messages) {
29→    for (const tc of msg.toolCalls ?? []) {
30→      allToolCalls.push(tc);
31→    }
32→  }
33→
34→  return (
35→    <div className="py-1">
36→      <button
37→        onClick={() => setExpanded((v) => !v)}
38→        aria-expanded={expanded}
39→        className="flex w-full items-center gap-2 rounded-md px-3 py-1.5 text-xs text-muted-foreground hover:bg-muted/50 transition-colors"
40→      >
41→        <ChevronRight
42→          className={cn(
43→            "size-3 shrink-0 transition-transform",
44→            expanded && "rotate-90"
45→          )}
46→        />
47→        <span className="font-mono">{group.summary}</span>
48→      </button>
49→
50→      {!expanded && allToolCalls.length > 0 && (
51→        <div className="ml-5 mt-0.5 space-y-0.5 pl-3">
52→          {allToolCalls.map((tc, i) => (
53→            <div key={`${tc.toolUseId ?? i}`} className="flex items-center gap-1.5 text-[10px] text-muted-foreground/70 truncate">
54→              <span className={cn("inline-block size-1.5 shrink-0 rounded-full", TOOL_COLORS[tc.name] ?? "bg-muted-foreground/50")} />
55→              <span className="font-mono shrink-0">{tc.name}</span>
56→              {tc.resultPreview && (
57→                <span className="truncate opacity-60">{tc.resultPreview}</span>
58→              )}
59→            </div>
60→          ))}
61→        </div>
62→      )}
63→
64→      {expanded && (
65→        <div className="ml-5 mt-1 space-y-1 border-l border-muted pl-3">
66→          {group.messages.map((msg) => (
67→            <Message key={msg.id} message={msg} />
68→          ))}
69→        </div>
70→      )}
71→    </div>
72→  );
73→}
