 84→/**
 85→ * Extract displayable text from a Claude assistant message.
 86→ * Content blocks may be text, tool_use, or tool_result — each is
 87→ * handled defensively since the array structure can vary.
 88→ */
 89→function extractText(msg: ClaudeAssistant): string {
 90→  const blocks = msg.message?.content;
 91→  if (!blocks || !Array.isArray(blocks)) return "";
 92→  return blocks
 93→    .map((b) => {
 94→      if (b.type === "text") return b.text;
 95→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 96→      if (b.type === "tool_result") {
 97→        const c = (b as { content?: unknown }).content;
 98→        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
 99→      }
100→      return "";
101→    })
102→    .filter(Boolean)
103→    .join("\n");
104→}
105→
106→/** Module-level counter for generating unique message IDs. */
107→let msgCounter = 0;
108→function nextId() {
109→  return `msg-${Date.now()}-${++msgCounter}`;
110→}
111→
112→/**
113→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
114→ * Used both for live messages and for replaying message_history.
115→ */
116→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
117→  if (relayMsg.type === "relay") {
118→    const msg = relayMsg.message;
119→
120→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
121→      const init = msg as ClaudeSystemInit;
122→      return {
123→        id: nextId(),
124→        role: "system",
125→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
126→        timestamp: Date.now(),
127→      };
128→    }
129→
130→    if (msg.type === "user") {
131→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
132→      // Only render human-typed user messages (string content).
133→      // CLI tool_result messages have array content — these are internal
134→      // protocol messages and are only visible in the raw message viewer.
135→      if (typeof rawContent !== "string") return null;
136→      if (!rawContent.trim()) return null;
137→      return {
138→        id: nextId(),
139→        role: "user",
140→        content: rawContent,
141→        timestamp: Date.now(),
142→      };
143→    }
144→
145→    if (msg.type === "assistant") {
146→      const assistant = msg as ClaudeAssistant;
147→      const text = extractText(assistant);
148→      if (!text) return null;
149→
150→      const blocks = assistant.message?.content ?? [];
151→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
152→
153→      // Build a map of tool_result blocks keyed by tool_use_id for preview extraction
154→      const resultMap = new Map<string, string>();
155→      for (const b of blocks) {
156→        if (b.type === "tool_result") {
157→          const tr = b as { tool_use_id?: string; content?: unknown };
158→          if (tr.tool_use_id) {
159→            const raw = typeof tr.content === "string" ? tr.content : JSON.stringify(tr.content ?? "");
160→            const firstLine = raw.split("\n")[0];
161→            resultMap.set(tr.tool_use_id, firstLine.length > 120 ? firstLine.slice(0, 117) + "..." : firstLine);
162→          }
163→        }
164→      }
165→
166→      const toolCalls: ToolCallInfo[] = blocks
167→        .filter((b) => b.type === "tool_use")
168→        .map((b) => ({
169→          name: (b as { name: string }).name,
170→          toolUseId: (b as { id: string }).id,
171→          resultPreview: resultMap.get((b as { id: string }).id),
172→        }));
173→      const isToolOnly = !hasText && toolCalls.length > 0;
174→
175→      return {
176→        id: nextId(),
177→        role: "assistant",
178→        content: text,
179→        timestamp: Date.now(),
180→        toolCalls,
181→        isToolOnly,
182→      };
183→    }
184→
185→    if (msg.type === "result") {
186→      const result = msg as ClaudeResult;
187→      const summary = result.is_error
188→        ? `Error: ${result.error}`
189→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
190→      return {
191→        id: nextId(),
192→        role: "system",
193→        content: summary,
194→        timestamp: Date.now(),
195→      };
196→    }
197→
198→    if (msg.type === "control_request") {
199→      const cr = msg as ClaudeControlRequest;
200→
201→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
202→      if (cr.request.tool_name === "AskUserQuestion") {
203→        const input = cr.request.input as { questions?: UserQuestion[] };
204→        const questions = Array.isArray(input.questions) ? input.questions : [];
205→        return {
206→          id: nextId(),
207→          role: "system",
208→          content: "Question from Claude",
209→          timestamp: Date.now(),
210→          userQuestion: {
211→            requestId: cr.request_id,
212→            questions,
213→          },
214→        };
215→      }
216→
217→      return {
218→        id: nextId(),
219→        role: "system",
220→        content: `Tool approval requested: ${cr.request.tool_name}`,
221→        timestamp: Date.now(),
222→        controlRequest: {
223→          id: cr.request_id,
224→          tool_name: cr.request.tool_name,
225→          input: cr.request.input,
226→          description: cr.request.description,
227→        },
228→      };
229→    }
230→  }
231→
232→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
233→    return {
234→      id: nextId(),
235→      role: "system",
236→      content: `Error: ${relayMsg.error}`,
237→      timestamp: Date.now(),
238→    };
239→  }
240→
241→  return null;
242→}
