249→export function useWebSocket() {
250→  const wsRef = useRef<WebSocket | null>(null);
251→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
252→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
253→  const closingRef = useRef(false);
254→  const [connected, setConnected] = useState(false);
255→  /** True once we've received the initial agent_list from the server. */
256→  const [initialLoadDone, setInitialLoadDone] = useState(false);
257→
258→  // Multi-agent state
259→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
260→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
261→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
262→
263→  // Task state
264→  const [tasks, setTasks] = useState<Task[]>([]);
265→
266→  // Workspace state
267→  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
268→  const [activeWorkspaceId, setActiveWorkspaceIdState] = useState<string | null>(null);
269→  const [directoryListing, setDirectoryListing] = useState<{ path: string; entries: DirectoryEntry[] } | null>(null);
270→
271→  // Per-agent deduplication: track count of processed messages per agent
272→  // to avoid duplicating messages already in local state during history replay.
273→  const processedCountRef = useRef<Map<string, number>>(new Map());
274→
275→  // Track which agents have had their history loaded (lazy loading).
276→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
277→
278→  /** Immutably update a single agent's state in the Map. */
279→  const updateAgent = useCallback(
280→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
281→      setAgents((prev) => {
282→        const existing = prev.get(agentId);
283→        if (!existing) return prev;
284→        const next = new Map(prev);
285→        next.set(agentId, updater(existing));
286→        return next;
287→      });
288→    },
289→    []
290→  );
291→
292→  const connect = useCallback(() => {
293→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
294→    if (wsRef.current) {
295→      wsRef.current.close();
296→      wsRef.current = null;
297→    }
298→
299→    // Reset dedup counts on new connection — server will send fresh history
300→    processedCountRef.current.clear();
301→    setInitialLoadDone(false);
302→    setLoadedAgents(new Set());
303→
304→    log("connecting to", WS_URL);
305→    const ws = new WebSocket(WS_URL);
306→    wsRef.current = ws;
307→
308→    ws.onopen = () => {
309→      log("connected");
310→      setConnected(true);
311→    };
312→
313→    ws.onclose = () => {
314→      log("disconnected, closingRef =", closingRef.current);
315→      setConnected(false);
316→      wsRef.current = null;
317→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
318→      if (closingRef.current) return;
319→      // Reconnection guard: clear any existing timer before scheduling
320→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
321→      log("scheduling reconnect in 2s");
322→      reconnectTimer.current = setTimeout(() => connect(), 2000);
323→    };
324→
325→    ws.onerror = (e) => {
326→      log("error", e);
327→      // onclose will fire after onerror, which triggers reconnect
328→    };
329→
330→    ws.onmessage = (event) => {
331→      let data: ServerMessage;
332→      try {
333→        data = JSON.parse(event.data as string);
334→      } catch {
335→        return;
336→      }
337→
338→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
339→
340→      // ── workspace_list: full workspace list from server ──
341→      if (data.type === "workspace_list") {
342→        const wsList = (data as { workspaces: Workspace[] }).workspaces;
343→        log("workspace_list:", wsList.length, "workspaces");
344→        setWorkspaces(wsList);
345→        return;
346→      }
347→
348→      // ── directory_listing: response to browse_directory ──
349→      if (data.type === "directory_listing") {
350→        const listing = data as { path: string; entries: DirectoryEntry[] };
351→        log("directory_listing:", listing.path, listing.entries.length, "entries");
352→        setDirectoryListing({ path: listing.path, entries: listing.entries });
353→        return;
354→      }
355→
356→      // ── task_list: full task list from server ──
357→      if (data.type === "task_list") {
358→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
359→        setTasks((data as ServerTaskList).tasks);
360→        return;
361→      }
362→
363→      // ── task_updated: single task changed ──
364→      if (data.type === "task_updated") {
365→        const updated = (data as ServerTaskUpdated).task;
366→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
367→        return;
368→      }
369→
370→      // ── task_deleted: remove task ──
371→      if (data.type === "task_deleted") {
372→        const deletedId = (data as ServerTaskDeleted).taskId;
373→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
374→        return;
375→      }
376→
377→      // ── message_history: replay full history from server ──
378→      if (data.type === "message_history") {
379→        const historyMsg = data as ServerMessageHistory;
380→        const agentId = historyMsg.agentId;
381→        const serverMessages = historyMsg.messages;
382→        log("message_history:", agentId, serverMessages.length, "raw msgs");
383→
384→        // Convert all server messages to ChatMessages + extract raw Claude messages
385→        const chatMessages: ChatMessage[] = [];
386→        const rawMessages: ClaudeMessage[] = [];
387→        for (const sm of serverMessages) {
388→          if (sm.type === "relay") {
389→            rawMessages.push(sm.message);
390→          }
391→          const cm = relayChatMessage(agentId, sm);
392→          if (cm) chatMessages.push(cm);
393→        }
394→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
395→
396→        // Always replace local messages with server history (source of truth).
397→        setAgents((prev) => {
398→          const existing = prev.get(agentId);
399→          if (!existing) {
400→            log("message_history:", agentId, "agent not in map yet, creating");
401→            const next = new Map(prev);
402→            next.set(agentId, {
403→              status: "idle",
404→              messages: chatMessages,
405→              rawMessages,
406→              label: "",
407→              tmuxSession: null,
408→              createdAt: 0,
409→            });
410→            return next;
411→          }
412→          const next = new Map(prev);
413→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
414→          return next;
415→        });
416→
417→        processedCountRef.current.set(agentId, chatMessages.length);
418→        setLoadedAgents((prev) => {
419→          if (prev.has(agentId)) return prev;
420→          const next = new Set(prev);
421→          next.add(agentId);
422→          return next;
423→        });
424→        return;
425→      }
426→
427→      // ── history_cleared: wipe local messages for this agent ──
428→      if (data.type === "history_cleared") {
429→        updateAgent(data.agentId, (prev) => ({
430→          ...prev,
431→          messages: [],
432→          rawMessages: [],
433→        }));
434→        processedCountRef.current.set(data.agentId, 0);
435→        return;
436→      }
437→
438→      // ── cli_disconnected: show system message ──
439→      if (data.type === "cli_disconnected") {
440→        updateAgent(data.agentId, (prev) => ({
441→          ...prev,
442→          messages: [
443→            ...prev.messages,
444→            {
445→              id: nextId(),
446→              role: "system",
447→              content: "CLI session ended",
448→              timestamp: Date.now(),
449→            },
450→          ],
451→        }));
452→        return;
453→      }
454→
455→      // ── cli_connected: show system message ──
456→      if (data.type === "cli_connected") {
457→        updateAgent(data.agentId, (prev) => ({
458→          ...prev,
459→          messages: [
460→            ...prev.messages,
461→            {
462→              id: nextId(),
463→              role: "system",
464→              content: "CLI reconnected",
465→              timestamp: Date.now(),
466→            },
467→          ],
468→        }));
469→        return;
470→      }
471→
472→      // ── agent_list: reconcile sidebar state from server ──
473→      if (data.type === "agent_list") {
474→        const serverAgents = data.agents as AgentInfo[];
475→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
476→        setAgents((prev) => {
477→          const next = new Map(prev);
478→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
479→
480→          // Update or add agents from server
481→          for (const info of serverAgents) {
482→            const existing = next.get(info.agentId);
483→            if (existing) {
484→              next.set(info.agentId, {
485→                ...existing,
486→                status: info.status,
487→                tmuxSession: info.tmuxSession,
488→                label: info.label,
489→              });
490→            } else {
491→              next.set(info.agentId, {
492→                status: info.status,
493→                messages: [],
494→                rawMessages: [],
495→                label: info.label,
496→                tmuxSession: info.tmuxSession,
497→                createdAt: info.createdAt,
498→              });
499→            }
500→          }
501→
502→          // Remove agents no longer on the server
503→          for (const id of next.keys()) {
504→            if (!serverIds.has(id)) {
505→              next.delete(id);
506→            }
507→          }
508→
509→          return next;
510→        });
511→        setAgentOrder(serverAgents.map((a) => a.agentId));
512→        setInitialLoadDone(true);
513→
514→        // Auto-select the first agent on initial load when nothing is selected
515→        setActiveAgentId((prev) => {
516→          if (prev !== null) return prev;
517→          if (serverAgents.length === 0) return null;
518→          return serverAgents[0].agentId;
519→        });
520→        return;
521→      }
522→
523→      // ── spawned: auto-select the newly created agent ──
524→      if (data.type === "spawned") {
525→        setActiveAgentId(data.agentId);
526→        return;
527→      }
528→
529→      // ── status: update a specific agent's status ──
530→      if (data.type === "status") {
531→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
532→        return;
533→      }
534→
535→      // ── error: append to agent's message list ──
536→      if (data.type === "error") {
537→        updateAgent(data.agentId, (prev) => ({
538→          ...prev,
539→          messages: [
540→            ...prev.messages,
541→            {
542→              id: nextId(),
543→              role: "system",
544→              content: `Error: ${data.error}`,
545→              timestamp: Date.now(),
546→            },
547→          ],
548→        }));
549→        // Track processed count for dedup
550→        processedCountRef.current.set(
551→          data.agentId,
552→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
553→        );
554→        return;
555→      }
556→
557→      // ── relay: append claude message to agent's history ──
558→      if (data.type === "relay") {
559→        const agentId = data.agentId;
560→        const rawMsg = data.message;
561→        const chatMsg = relayChatMessage(agentId, data);
562→
563→        updateAgent(agentId, (prev) => ({
564→          ...prev,
565→          rawMessages: [...prev.rawMessages, rawMsg],
566→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
567→        }));
568→        if (chatMsg) {
569→          // Track processed count for dedup
570→          processedCountRef.current.set(
571→            agentId,
572→            (processedCountRef.current.get(agentId) ?? 0) + 1
573→          );
574→        }
575→        return;
576→      }
577→    };
578→  }, [updateAgent]);
579→
580→  useEffect(() => {
581→    closingRef.current = false;
582→    connect();
583→    return () => {
584→      closingRef.current = true;
585→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
586→      wsRef.current?.close();
587→    };
588→  }, [connect]);
589→
590→  const send = useCallback((data: object) => {
591→    if (wsRef.current?.readyState === WebSocket.OPEN) {
592→      wsRef.current.send(JSON.stringify(data));
593→    }
594→  }, []);
595→
596→  // Request history for the active agent if not already loaded.
597→  useEffect(() => {
598→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
599→    log("requesting history for", activeAgentId);
600→    send({ type: "request_history", agentId: activeAgentId });
601→  }, [activeAgentId, loadedAgents, send]);
602→
603→  const spawnAgent = useCallback(
604→    (prompt: string) => {
605→      send({ type: "spawn", prompt });
606→    },
607→    [send]
608→  );
609→
610→  const sendMessage = useCallback(
611→    (content: string) => {
612→      if (!activeAgentId) return;
613→      // Optimistically add user message to local state
614→      updateAgent(activeAgentId, (prev) => ({
615→        ...prev,
616→        messages: [
617→          ...prev.messages,
618→          {
619→            id: nextId(),
620→            role: "user",
621→            content,
622→            timestamp: Date.now(),
623→          },
624→        ],
625→      }));
626→      send({ type: "send_message", agentId: activeAgentId, content });
627→    },
628→    [send, activeAgentId, updateAgent]
629→  );
630→
631→  const respondToControl = useCallback(
632→    (requestId: string, allow: boolean) => {
633→      if (!activeAgentId) return;
634→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
635→      updateAgent(activeAgentId, (prev) => ({
636→        ...prev,
637→        messages: prev.messages.map((m) =>
