640→            : m
641→        ),
642→      }));
643→    },
644→    [send, activeAgentId, updateAgent]
645→  );
646→
647→  /** Respond to an AskUserQuestion control request with the user's selections. */
648→  const respondToUserQuestion = useCallback(
649→    (requestId: string, answers: Record<string, string>) => {
650→      if (!activeAgentId) return;
651→      send({
652→        type: "control_response",
653→        agentId: activeAgentId,
654→        request_id: requestId,
655→        allow: true,
656→        answers,
657→      });
658→      updateAgent(activeAgentId, (prev) => ({
659→        ...prev,
660→        messages: prev.messages.map((m) =>
661→          m.userQuestion?.requestId === requestId
662→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
663→            : m
664→        ),
665→      }));
666→    },
667→    [send, activeAgentId, updateAgent]
668→  );
669→
670→  // ── Agent management actions ──────────────────────────────────────────────
671→
672→  const killAgent = useCallback(
673→    (agentId: string) => {
674→      send({ type: "kill_agent", agentId });
675→    },
676→    [send]
677→  );
678→
679→  const deleteAgent = useCallback(
680→    (agentId: string) => {
681→      send({ type: "delete_agent", agentId });
682→      // Deselect if we just deleted the active agent
683→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
684→    },
685→    [send]
686→  );
687→
688→  const renameAgent = useCallback(
689→    (agentId: string, label: string) => {
690→      send({ type: "rename_agent", agentId, label });
691→    },
692→    [send]
693→  );
694→
695→  const clearHistory = useCallback(
696→    (agentId: string) => {
697→      send({ type: "clear_history", agentId });
698→    },
699→    [send]
700→  );
701→
702→  // ── Task actions ──────────────────────────────────────────────────────────
703→
704→  const createTask = useCallback(
705→    (title: string, description: string, priority: TaskPriority) => {
706→      send({ type: "create_task", title, description, priority });
707→    },
708→    [send]
709→  );
710→
711→  const updateTask = useCallback(
712→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
